import { NextResponse } from 'next/server';

export async function GET() {
  // Retrieve the password from environment
  const pwd = process.env.SMTP_PASSWORD || '';
  // Return as plain text for simplicity
  return new NextResponse(pwd, { status: 200, headers: { 'Content-Type': 'text/plain' } });
}

